import sys
import time
from concurrent.futures import Future, ThreadPoolExecutor

import pytest


class Bad(Exception):
    def __init__(self, n: int) -> None:
        self.n = n


def check(x: int) -> int:
    if x % 2 == 1:
        raise Bad(x)
    return x


def all_even(xs: list[int]) -> list[int]:
    """Run check on every element of xs in parallel using a thread pool.

    Returns the checked values in input order. If any elements are bad,
    raises the Bad for the lowest-index bad element, regardless of which
    thread finishes first.
    """
    if not xs:
        return []
    with ThreadPoolExecutor(max_workers=min(32, len(xs))) as pool:
        futures: list[Future[int]] = [pool.submit(check, x) for x in xs]
        results: list[int] = []
        try:
            # Collect in index order: the first future that raises is the
            # lowest-index failure, since all earlier ones succeeded.
            for fut in futures:
                results.append(fut.result())
        except BaseException:
            for fut in futures:
                fut.cancel()
            raise
    return results


def test_all_even_ok_preserves_order() -> None:
    assert all_even([2, 4, 6, 8]) == [2, 4, 6, 8]


def test_all_even_empty() -> None:
    assert all_even([]) == []


def test_single_bad() -> None:
    with pytest.raises(Bad) as excinfo:
        all_even([2, 4, 5, 6])
    assert excinfo.value.n == 5


def test_lowest_index_not_lowest_value() -> None:
    # Index 1 (value 7) is the lowest-index bad element; value 3 is smaller.
    with pytest.raises(Bad) as excinfo:
        all_even([4, 7, 3])
    assert excinfo.value.n == 7


def test_lowest_index_wins_when_it_finishes_last(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    original = check

    def slow_check(x: int) -> int:
        if x == 9:
            time.sleep(0.3)
        return original(x)

    monkeypatch.setattr(sys.modules[__name__], "check", slow_check)
    with pytest.raises(Bad) as excinfo:
        all_even([2, 9, 4, 3, 5])
    assert excinfo.value.n == 9


def test_ok_order_preserved_with_varied_delays(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    original = check

    def slow_check(x: int) -> int:
        time.sleep(0.2 if x == 2 else 0.0)
        return original(x)

    monkeypatch.setattr(sys.modules[__name__], "check", slow_check)
    assert all_even([2, 4, 6]) == [2, 4, 6]
